const incoming = $input.item.json ?? {};
const body = incoming.body ?? incoming;
const result = body.result ?? {};

function parseMultivalue(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(v).trim()).filter(Boolean);
  }
  if (value === null || value === undefined || value === '') return [];
  return String(value)
    .split(/[\n,]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
}

const targetedUsers = parseMultivalue(
  firstValue(result.targeted_users, result.user, result.users, result.target_user)
);
const targetedHosts = parseMultivalue(
  firstValue(result.targeted_hosts, result.host, result.hosts, result.dest_host)
);

const failedAttempts = Number.parseInt(
  firstValue(result.failed_attempts, result.count, result.event_count, 0),
  10
) || 0;

let severity = String(
  firstValue(body.severity, body.urgency, result.severity, result.urgency)
).toLowerCase().trim();

const aliases = {
  crit: 'critical',
  severe: 'critical',
  warning: 'medium',
  info: 'informational'
};
severity = aliases[severity] ?? severity;

const validSeverities = ['critical', 'high', 'medium', 'low', 'informational'];

if (!validSeverities.includes(severity)) {
  if (failedAttempts >= 20) severity = 'critical';
  else if (failedAttempts >= 10) severity = 'high';
  else if (failedAttempts >= 3) severity = 'medium';
  else severity = 'low';
}

const severityMeta = {
  critical: { color: '#b91c1c', emoji: '🔴', label: 'CRITICAL' },
  high: { color: '#c2410c', emoji: '🟠', label: 'HIGH' },
  medium: { color: '#a16207', emoji: '🟡', label: 'MEDIUM' },
  low: { color: '#4d7c0f', emoji: '🟢', label: 'LOW' },
  informational: { color: '#0369a1', emoji: '🔵', label: 'INFORMATIONAL' }
};

const meta = severityMeta[severity];

return {
  json: {
    alert_id: String(firstValue(body.sid, result.sid)),
    search_name: String(firstValue(body.search_name, result.search_name, body.name, 'Splunk alert')),
    app: String(firstValue(body.app, result.app)),
    owner: String(firstValue(body.owner, result.owner)),
    results_link: String(firstValue(body.results_link, result.results_link)),
    severity,
    severity_label: meta.label,
    severity_color: meta.color,
    severity_emoji: meta.emoji,
    src_ip: String(firstValue(result.src_ip, result.source_ip, result.src, result.rhost)),
    failed_attempts: failedAttempts,
    targeted_users: targetedUsers,
    targeted_users_str: targetedUsers.join(', ') || 'N/A',
    targeted_hosts: targetedHosts,
    targeted_hosts_str: targetedHosts.join(', ') || 'N/A',
    unique_users: Number.parseInt(result.unique_users, 10) || targetedUsers.length,
    unique_hosts: Number.parseInt(result.unique_hosts, 10) || targetedHosts.length,
    first_seen: String(firstValue(result.first_seen, result.earliest_time)),
    last_seen: String(firstValue(result.last_seen, result.latest_time)),
    received_at: new Date().toISOString(),
    raw_result: result
  }
};

